-- Schema only, extracted read-only from accepted live.sqlite; contains no football facts.
CREATE TABLE acquisition_attempts(attempt_id INTEGER PRIMARY KEY,source_id TEXT,status TEXT,http_status INTEGER,reason TEXT,artifact_id TEXT,attempted_at TEXT);
CREATE TABLE acquisition_sources(source_id TEXT PRIMARY KEY,club_id INTEGER,organization TEXT,url TEXT,policy_json TEXT);
CREATE TABLE affiliation_changes(change_id TEXT PRIMARY KEY,club_id INTEGER,player_id INTEGER,before_json TEXT,after_json TEXT,effective_date TEXT,source_json TEXT,reason TEXT,recorded_at TEXT);
CREATE TABLE clubs(club_id INTEGER PRIMARY KEY,club_key TEXT UNIQUE,name TEXT,country TEXT);
CREATE TABLE competitions(competition_id TEXT PRIMARY KEY,name TEXT,category TEXT,country TEXT);
CREATE TABLE identity_issues(issue_id TEXT PRIMARY KEY,club_id INTEGER,match_id INTEGER,player_id INTEGER,kind TEXT,detail TEXT,observed_at TEXT);
CREATE TABLE live_catalogs(run_id TEXT,club_id INTEGER,provider TEXT,status TEXT,payload_json TEXT,PRIMARY KEY(run_id,club_id,provider));
CREATE TABLE live_checkpoints(club_id INTEGER,scope TEXT,checked_through TEXT,status TEXT,run_id TEXT,PRIMARY KEY(club_id,scope));
CREATE TABLE live_conflicts(conflict_id TEXT PRIMARY KEY,run_id TEXT,club_id INTEGER,match_id TEXT,kind TEXT,payload_json TEXT,resolved INTEGER DEFAULT 0);
CREATE TABLE live_documents(url TEXT PRIMARY KEY,club_id INTEGER,match_id TEXT,provider TEXT,body_sha256 TEXT,checked_at TEXT,source_json TEXT);
CREATE TABLE live_pending_sheets(club_id INTEGER,match_id TEXT,provider TEXT,version_sha TEXT,payload_json TEXT,staged_at TEXT,PRIMARY KEY(club_id,match_id,provider,version_sha));
CREATE TABLE live_rollups(club_id INTEGER,player_id INTEGER,as_of TEXT,window_days INTEGER,minutes REAL,unknown_rows INTEGER,scope TEXT DEFAULT 'CLUB_ONLY',PRIMARY KEY(club_id,player_id,as_of,window_days));
CREATE TABLE live_runs(run_id TEXT PRIMARY KEY,started_at TEXT,finished_at TEXT,origin TEXT,status TEXT,payload_json TEXT);
CREATE TABLE live_scan_windows(club_id INTEGER,provider TEXT,completed_at TEXT,PRIMARY KEY(club_id,provider));
CREATE TABLE live_sheets(club_id INTEGER,match_id TEXT,provider TEXT,version_sha TEXT,payload_json TEXT,verified_at TEXT,PRIMARY KEY(club_id,match_id,provider,version_sha));
CREATE TABLE live_tasks(url TEXT PRIMARY KEY,club_id INTEGER,date TEXT,provider TEXT,status TEXT,attempts INTEGER DEFAULT 0,next_retry TEXT,last_error TEXT,last_run TEXT,payload_json TEXT);
CREATE TABLE manual_actions(source_id TEXT PRIMARY KEY,status TEXT,url TEXT,last_step TEXT,next_action TEXT,login_required TEXT,season_selection TEXT,export_button TEXT,recommended_format TEXT,destination TEXT);
CREATE TABLE match_processing(club_id INTEGER,match_id INTEGER,artifact_id TEXT,acquisition_status TEXT,processing_status TEXT,reason TEXT,observed_at TEXT,PRIMARY KEY(club_id,match_id));
CREATE TABLE matches(match_id TEXT PRIMARY KEY,home_id INTEGER,away_id INTEGER,kickoff TEXT,local_date TEXT,period_id TEXT REFERENCES periods,competition_id INTEGER REFERENCES competitions,result TEXT,artifact_id TEXT REFERENCES raw_artifacts,observed_at TEXT,source_competition_id INTEGER, scheduled_kickoff TEXT, match_state TEXT, metadata_json TEXT);
CREATE TABLE official_identity_candidates(snapshot_id TEXT,local_member_id TEXT,fotmob_player_id INTEGER,method TEXT,review_status TEXT,evidence_json TEXT,PRIMARY KEY(snapshot_id,local_member_id,fotmob_player_id));
CREATE TABLE official_membership(snapshot_id TEXT REFERENCES official_snapshots,official_player_id TEXT,source_name TEXT,date_of_birth TEXT,shirt_number TEXT,fotmob_player_id INTEGER,provenance TEXT,PRIMARY KEY(snapshot_id,official_player_id));
CREATE TABLE official_membership_details(snapshot_id TEXT,local_member_id TEXT,ordinal INTEGER,position TEXT,nationality TEXT,country_code TEXT,official_source_player_id TEXT,line_start INTEGER,line_end INTEGER,PRIMARY KEY(snapshot_id,local_member_id),FOREIGN KEY(snapshot_id,local_member_id) REFERENCES official_membership(snapshot_id,official_player_id));
CREATE TABLE official_snapshots(snapshot_id TEXT PRIMARY KEY,source_id TEXT REFERENCES acquisition_sources,club_id INTEGER,period_id TEXT REFERENCES periods,artifact_id TEXT REFERENCES raw_artifacts,captured_at TEXT,effective_from TEXT,effective_to TEXT,acquisition_status TEXT,parse_status TEXT,content_review_status TEXT);
CREATE TABLE periods(period_id TEXT PRIMARY KEY,season TEXT,half TEXT,start_date TEXT,end_exclusive TEXT,timezone TEXT);
CREATE TABLE player_affiliations(affiliation_id TEXT PRIMARY KEY,player_id INTEGER REFERENCES players,club_id INTEGER,relationship_type TEXT CHECK(relationship_type IN ('FIRST_TEAM','LOAN_IN','LOAN_OUT','ACADEMY','ACADEMY_CALLED_UP','TRANSFERRED_OUT','UNVERIFIED')),start_date TEXT,end_date TEXT,verified_as_of TEXT,verification_status TEXT,source_json TEXT,reason TEXT,date_precision TEXT);
CREATE TABLE player_eligibility(eligibility_id TEXT PRIMARY KEY,player_id INTEGER REFERENCES players,club_id INTEGER,classification TEXT,regular_member INTEGER,start_date TEXT,end_date TEXT,verified_as_of TEXT,verification_status TEXT,source_json TEXT,reason TEXT);
CREATE TABLE player_match_minutes(club_id INTEGER,match_id INTEGER REFERENCES matches,player_id INTEGER REFERENCES players,minutes REAL,minutes_status TEXT,played INTEGER,artifact_id TEXT, participation_status TEXT, reported_minutes REAL, derived_minutes REAL, method TEXT, evidence_json TEXT, revision INTEGER DEFAULT 1,PRIMARY KEY(club_id,match_id,player_id));
CREATE TABLE player_registration(player_id INTEGER,club_id INTEGER,registration_type TEXT,as_of TEXT,source_json TEXT,PRIMARY KEY(player_id,club_id,registration_type,as_of));
CREATE TABLE players(player_id INTEGER PRIMARY KEY,display_name TEXT,identity_status TEXT DEFAULT 'source_observed_not_independently_verified');
CREATE TABLE provider_identities(mapping_id TEXT PRIMARY KEY,source_id TEXT,official_player_id TEXT,fotmob_player_id INTEGER,full_name TEXT,date_of_birth TEXT,club_id INTEGER,season TEXT,confidence TEXT,evidence_artifact_id TEXT,review_status TEXT);
CREATE TABLE raw_artifacts(artifact_id TEXT PRIMARY KEY,source_id TEXT,path TEXT,sha256 TEXT,size INTEGER,kind TEXT,acquired_at TEXT,observed_at TEXT,effective_period TEXT);
CREATE TABLE squad_observations(club_id INTEGER,match_id INTEGER REFERENCES matches,player_id INTEGER REFERENCES players,role TEXT,shirt_number TEXT,source_name TEXT,json_path TEXT,artifact_id TEXT REFERENCES raw_artifacts,observed_at TEXT,PRIMARY KEY(club_id,match_id,player_id));
CREATE TABLE update_jobs(job_key TEXT PRIMARY KEY,kind TEXT,url TEXT,status TEXT,last_checked TEXT,reason TEXT);
CREATE TABLE validation_applied_inputs(input_id TEXT PRIMARY KEY,logical_date TEXT,payload_hash TEXT);
CREATE TABLE validation_daily_logs(logical_date TEXT PRIMARY KEY,payload_json TEXT);
CREATE TABLE validation_fact_revisions(revision_id TEXT PRIMARY KEY,club_id INTEGER,match_id TEXT,player_id INTEGER,logical_date TEXT,reason TEXT,before_json TEXT,after_json TEXT);
CREATE TABLE validation_ground_truth_checks(record_id TEXT PRIMARY KEY,payload_json TEXT);
CREATE TABLE validation_match_aliases(alias TEXT PRIMARY KEY,match_id TEXT REFERENCES matches,reason TEXT);
CREATE TABLE validation_match_sheets(club_id INTEGER,match_id TEXT,provider TEXT,source_sha256 TEXT,payload_json TEXT,PRIMARY KEY(club_id,match_id,provider,source_sha256));
CREATE TABLE validation_national_reference(player_id INTEGER,match_id TEXT,payload_json TEXT,PRIMARY KEY(player_id,match_id));
CREATE TABLE validation_player_aliases(provider_key TEXT PRIMARY KEY,player_id INTEGER REFERENCES players,identity_json TEXT);
CREATE TABLE validation_quality_metrics(record_id TEXT PRIMARY KEY,payload_json TEXT);
CREATE TABLE validation_reconciliation(record_id TEXT PRIMARY KEY,payload_json TEXT);
CREATE TABLE validation_reference_definition(club_id INTEGER PRIMARY KEY,definition_json TEXT);
CREATE TABLE validation_rolling(club_id INTEGER,player_id INTEGER,as_of TEXT,window_days INTEGER,minutes REAL,unknown_rows INTEGER,PRIMARY KEY(club_id,player_id,as_of,window_days));
CREATE TABLE validation_roster_differences(record_id TEXT PRIMARY KEY,payload_json TEXT);
CREATE TABLE validation_roster_membership(club_id INTEGER,player_id INTEGER REFERENCES players,kind TEXT,first_seen TEXT,last_seen TEXT,effective_from TEXT,effective_to TEXT,source_json TEXT,PRIMARY KEY(club_id,player_id,kind));
CREATE TABLE validation_run_artifacts(artifact_name TEXT PRIMARY KEY,payload_json TEXT);
CREATE TABLE validation_source_evidence(evidence_id TEXT PRIMARY KEY,payload_json TEXT NOT NULL);
CREATE VIEW combined_membership AS SELECT club_id,period_id,player_id,MAX(baseline) listed_in_baseline,MAX(observed) observed_in_matchday FROM (SELECT club_id,period_id,player_id,0 baseline,1 observed FROM historical_membership UNION ALL SELECT club_id,period_id,player_id,1 baseline,0 observed FROM verified_baseline_membership) GROUP BY club_id,period_id,player_id;
CREATE VIEW historical_membership AS SELECT o.club_id,m.period_id,o.player_id,MIN(m.local_date) first_observed,MAX(m.local_date) last_observed,COUNT(*) match_evidence_count FROM squad_observations o JOIN matches m USING(match_id) GROUP BY o.club_id,m.period_id,o.player_id;
CREATE VIEW verified_baseline_membership AS SELECT s.club_id,s.period_id,b.fotmob_player_id player_id,s.snapshot_id FROM official_membership b JOIN official_snapshots s USING(snapshot_id) WHERE s.parse_status='VERIFIED' AND b.fotmob_player_id IS NOT NULL;
